/**
 * Event types come from the typed contract (../contract/events.ts, generated by the
 * backend). Nothing here is hand-written event shape; this module only adds the
 * defensive parse the contract asks for: keep, but don't render, unknown kinds.
 */
import { EVENT_KINDS, type Event, type EventKind } from "@contract";

export type {
  Approval,
  ApprovalKind,
  ApprovalNeededEvent,
  ApprovalResolvedEvent,
  Budget,
  Choice,
  Event,
  EventKind,
  Plan,
  StepEvent,
} from "@contract";
export { APPROVAL_KINDS, EVENT_KINDS } from "@contract";

/** An event whose kind this panel does not know: kept in the log, never rendered. */
export interface UnknownEvent {
  id: number;
  kind: string;
  run_id: string;
  unknown: true;
}

export type LogEvent = Event | UnknownEvent;

export type ParseResult =
  | { ok: true; event: LogEvent }
  | { ok: false; reason: string };

const KNOWN: ReadonlySet<string> = new Set(EVENT_KINDS);

export function isKnownKind(kind: string): kind is EventKind {
  return KNOWN.has(kind);
}

export function isKnown(event: LogEvent): event is Event {
  return !("unknown" in event);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Parse one SSE data payload. The envelope (id, kind, run_id) is checked; the rest is
 * trusted to be the contract's shape, which the backend writes only through its models.
 */
export function parseEvent(data: string): ParseResult {
  let value: unknown;
  try {
    value = JSON.parse(data);
  } catch {
    return { ok: false, reason: "The event is not valid JSON." };
  }
  if (!isRecord(value)) return { ok: false, reason: "The event is not an object." };
  const { id, kind, run_id: runId } = value;
  if (typeof id !== "number" || !Number.isInteger(id) || id <= 0) {
    return { ok: false, reason: "The event has no positive integer id." };
  }
  if (typeof kind !== "string" || kind === "") return { ok: false, reason: "The event has no kind." };
  if (typeof runId !== "string") return { ok: false, reason: "The event has no run id." };
  if (!isKnownKind(kind)) return { ok: true, event: { id, kind, run_id: runId, unknown: true } };
  return { ok: true, event: value as unknown as Event };
}

/** Insert an event keeping the log ordered by id and free of duplicates. */
export function appendEvent(log: readonly LogEvent[], event: LogEvent): LogEvent[] {
  const last = log[log.length - 1];
  if (last === undefined || event.id > last.id) return [...log, event];
  if (log.some((e) => e.id === event.id)) return log as LogEvent[];
  return [...log, event].sort((a, b) => a.id - b.id);
}

/** Only the events the panel understands, in order. */
export function knownEvents(log: readonly LogEvent[]): Event[] {
  return log.filter(isKnown);
}
